/// A route between two artists, or the news that there is none
public struct ArtistRoute: Codable, Equatable, Sendable {
    /// False when either end is not an artist the library holds a record by, or no route turned up within the search's bounds
    public var found: Bool
    /// In order, the first artist first. Empty when nothing was found
    public var stops: [RouteStop]
    /// How many hops rest on a record the two artists share
    public var factual: Int
    /// How many hops rest on a similarity source's opinion
    public var similar: Int

    public init(found: Bool, stops: [RouteStop], factual: Int, similar: Int) {
        self.found = found
        self.stops = stops
        self.factual = factual
        self.similar = similar
    }

    private enum CodingKeys: String, CodingKey {
        case found = "found"
        case stops = "stops"
        case factual = "factual"
        case similar = "similar"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.found = try container.decode(Bool.self, forKey: .found)
        self.stops = try container.decode([RouteStop].self, forKey: .stops)
        self.factual = try container.decode(Int.self, forKey: .factual)
        self.similar = try container.decode(Int.self, forKey: .similar)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.found, forKey: .found)
        try container.encode(self.stops, forKey: .stops)
        try container.encode(self.factual, forKey: .factual)
        try container.encode(self.similar, forKey: .similar)
    }
}

/// The station's live running order: what is airing, item by item
public struct StationOrder: Codable, Equatable, Sendable {
    /// What is on, for a console to draw. A label for this broadcast rather than the name of a stored object
    public var name: String
    /// What the operator asked the station to play, in their own words. It keeps steering every refill until the station is put on air again, so a console should show it rather than only accept it
    public var brief: String?
    /// Who is hosting this broadcast, when it named somebody. Absent means whichever persona the station has on air
    public var personaId: String?
    /// What that host is called, resolved as the order is read so a console need not fetch the persona list to draw a name
    public var personaLabel: String?
    /// Who presents beside the host on this broadcast, in order: the co-hosts the schedule put on for tonight. Absent is one voice
    public var coHostPersonaIds: [String]?
    public var mode: StationMode
    public var onEnd: StationOnEnd
    /// Who built it: `import`, `chart` or `director`
    public var source: String
    /// Where more material is pulled from, when it came from a playlist
    public var sourcePluginId: String?
    /// The playlist it was built from. With no `sourcePluginId`, a playlist the station owns
    public var sourcePlaylistId: String?
    /// The published chart this broadcast was built from, qualified with the plugin that offered it. Provenance rather than a binding: a chart is a fixed document, so it is read once and never topped up from
    public var sourceChartId: String?
    /// Whether this is a request show, on which each listener request is followed by records like it. Absent is an ordinary show
    public var requestShow: Bool?
    /// How many records follow each request on a request show. Present only on one
    public var requestFollowOn: Int?
    public var items: [StationOrderItem]

    public init(name: String, brief: String? = nil, personaId: String? = nil, personaLabel: String? = nil, coHostPersonaIds: [String]? = nil, mode: StationMode, onEnd: StationOnEnd, source: String, sourcePluginId: String? = nil, sourcePlaylistId: String? = nil, sourceChartId: String? = nil, requestShow: Bool? = nil, requestFollowOn: Int? = nil, items: [StationOrderItem]) {
        self.name = name
        self.brief = brief
        self.personaId = personaId
        self.personaLabel = personaLabel
        self.coHostPersonaIds = coHostPersonaIds
        self.mode = mode
        self.onEnd = onEnd
        self.source = source
        self.sourcePluginId = sourcePluginId
        self.sourcePlaylistId = sourcePlaylistId
        self.sourceChartId = sourceChartId
        self.requestShow = requestShow
        self.requestFollowOn = requestFollowOn
        self.items = items
    }

    private enum CodingKeys: String, CodingKey {
        case name = "name"
        case brief = "brief"
        case personaId = "personaId"
        case personaLabel = "personaLabel"
        case coHostPersonaIds = "coHostPersonaIds"
        case mode = "mode"
        case onEnd = "onEnd"
        case source = "source"
        case sourcePluginId = "sourcePluginId"
        case sourcePlaylistId = "sourcePlaylistId"
        case sourceChartId = "sourceChartId"
        case requestShow = "requestShow"
        case requestFollowOn = "requestFollowOn"
        case items = "items"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.name = try container.decode(String.self, forKey: .name)
        self.brief = try container.decodeIfPresent(String.self, forKey: .brief)
        self.personaId = try container.decodeIfPresent(String.self, forKey: .personaId)
        self.personaLabel = try container.decodeIfPresent(String.self, forKey: .personaLabel)
        self.coHostPersonaIds = try container.decodeIfPresent([String].self, forKey: .coHostPersonaIds)
        self.mode = try container.decode(StationMode.self, forKey: .mode)
        self.onEnd = try container.decode(StationOnEnd.self, forKey: .onEnd)
        self.source = try container.decode(String.self, forKey: .source)
        self.sourcePluginId = try container.decodeIfPresent(String.self, forKey: .sourcePluginId)
        self.sourcePlaylistId = try container.decodeIfPresent(String.self, forKey: .sourcePlaylistId)
        self.sourceChartId = try container.decodeIfPresent(String.self, forKey: .sourceChartId)
        self.requestShow = try container.decodeIfPresent(Bool.self, forKey: .requestShow)
        self.requestFollowOn = try container.decodeIfPresent(Int.self, forKey: .requestFollowOn)
        self.items = try container.decode([StationOrderItem].self, forKey: .items)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.name, forKey: .name)
        try container.encodeIfPresent(self.brief, forKey: .brief)
        try container.encodeIfPresent(self.personaId, forKey: .personaId)
        try container.encodeIfPresent(self.personaLabel, forKey: .personaLabel)
        try container.encodeIfPresent(self.coHostPersonaIds, forKey: .coHostPersonaIds)
        try container.encode(self.mode, forKey: .mode)
        try container.encode(self.onEnd, forKey: .onEnd)
        try container.encode(self.source, forKey: .source)
        try container.encodeIfPresent(self.sourcePluginId, forKey: .sourcePluginId)
        try container.encodeIfPresent(self.sourcePlaylistId, forKey: .sourcePlaylistId)
        try container.encodeIfPresent(self.sourceChartId, forKey: .sourceChartId)
